package domain

import (
	"fmt"
	"slices"
	"strings"
	"time"
)

// ClipID identifies a clip (UUID v7 generated by the application).
type ClipID string

// MediaRef is an opaque reference to a media file managed by an adapter.
type MediaRef string

// MessageRef is an opaque reference to the notification message(s) of a clip
// (e.g. Telegram chat and message ids), used to edit them as the state changes.
type MessageRef string

// ClipState is a state of the clip lifecycle (State pattern, CLAUDE.md §5).
type ClipState string

// Clip states.
const (
	StateDetected    ClipState = "detected"
	StatePreviewSent ClipState = "preview_sent"
	StateApproved    ClipState = "approved"
	StateDiscarded   ClipState = "discarded"
	StateExpired     ClipState = "expired"
	StateEditing     ClipState = "editing"
	StateRendered    ClipState = "rendered"
	StateDelivered   ClipState = "delivered"
	StatePublishing  ClipState = "publishing"
	StatePublished   ClipState = "published"
	StateFailed      ClipState = "failed"
)

// ClipStates lists every state in lifecycle order.
var ClipStates = []ClipState{
	StateDetected, StatePreviewSent, StateApproved, StateDiscarded, StateExpired,
	StateEditing, StateRendered, StateDelivered, StatePublishing, StatePublished, StateFailed,
}

// transitions is the state machine table (CLAUDE.md §5).
var transitions = map[ClipState][]ClipState{
	StateDetected:    {StatePreviewSent, StateFailed},
	StatePreviewSent: {StateApproved, StateDiscarded, StateExpired},
	StateApproved:    {StateEditing},
	StateEditing:     {StateRendered, StateFailed},
	StateRendered:    {StateDelivered, StateFailed},
	// Publication is requested by the human (button on the final video); a
	// failed upload goes back to delivered so it can be requested again.
	StateDelivered:  {StatePublishing},
	StatePublishing: {StatePublished, StateDelivered},
	StateFailed:     {StateApproved},
}

// Valid reports whether s is a known state.
func (s ClipState) Valid() bool { return slices.Contains(ClipStates, s) }

// Final reports whether no transition leaves s.
func (s ClipState) Final() bool {
	return s == StateDiscarded || s == StateExpired || s == StatePublished
}

// CanTransition reports whether the table allows from → to.
func CanTransition(from, to ClipState) bool {
	return slices.Contains(transitions[from], to)
}

// Decision is the human decision taken on a preview.
type Decision string

// Decisions recorded for calibration of the scorer.
const (
	DecisionApproved  Decision = "approved"
	DecisionDiscarded Decision = "discarded"
	DecisionExpired   Decision = "expired"
)

// Clip is the full lifecycle of a detected moment until delivery.
type Clip struct {
	ID          ClipID
	Streamer    string
	StreamID    StreamID
	Game        string
	StreamTitle string

	State  ClipState
	Moment Moment
	// PeakAt is the wall time of the event at the peak (for the preview latency).
	PeakAt time.Time
	// LiveOffset is the position of the peak since the start of the broadcast.
	LiveOffset time.Duration
	Window     Window
	// Timeline holds the per-second signal values over Window.
	Timeline []SignalPoint

	SourceMedia    MediaRef
	PreviewMedia   MediaRef
	FinalMedia     MediaRef
	PreviewMessage MessageRef
	// FinalMessage is the message(s) with the final video, edited as the
	// publication progresses.
	FinalMessage MessageRef

	// PublishedID and PublishedURL locate the published video (empty until
	// published); PublishError is why the last attempt failed.
	PublishedID  string
	PublishedURL string
	PublishError string

	Headline string
	PostText string
	// Plan is the validated edit, kept so a retry does not pay the editor again.
	Plan  *EditPlan
	Usage Usage
	Cost  MicroUSD

	FailureReason string
	FailedFrom    ClipState

	Decision  Decision
	DecidedAt time.Time

	CreatedAt time.Time
	UpdatedAt time.Time
	// StateTimes records when the clip last entered each state.
	StateTimes map[ClipState]time.Time
}

// NewClipParams are the inputs of NewClip.
type NewClipParams struct {
	ID       ClipID
	Streamer string
	Live     LiveStream
	Moment   Moment
	Window   Window
	Timeline []SignalPoint
	Source   MediaRef
	// PeakAt and LiveOffset locate the peak in wall time and in the broadcast.
	PeakAt     time.Time
	LiveOffset time.Duration
}

// NewClip creates a clip in the detected state.
func NewClip(p NewClipParams, now time.Time) (*Clip, error) {
	switch {
	case p.ID == "":
		return nil, fmt.Errorf("%w: clip id is empty", ErrInvalidArgument)
	case p.Streamer == "":
		return nil, fmt.Errorf("%w: clip streamer is empty", ErrInvalidArgument)
	case !p.Window.Valid():
		return nil, fmt.Errorf("%w: clip window %v–%v is invalid", ErrInvalidArgument, p.Window.From, p.Window.To)
	case !p.Window.Contains(p.Moment.Peak):
		return nil, fmt.Errorf("%w: peak %v outside window %v–%v", ErrInvalidArgument, p.Moment.Peak, p.Window.From, p.Window.To)
	case p.Source == "":
		return nil, fmt.Errorf("%w: clip source media is empty", ErrInvalidArgument)
	}
	now = now.UTC()
	return &Clip{
		ID:          p.ID,
		Streamer:    p.Streamer,
		StreamID:    p.Live.ID,
		Game:        p.Live.Game,
		StreamTitle: p.Live.Title,
		State:       StateDetected,
		Moment:      p.Moment.Clone(),
		PeakAt:      p.PeakAt.UTC(),
		LiveOffset:  p.LiveOffset,
		Window:      p.Window,
		Timeline:    slices.Clone(p.Timeline),
		SourceMedia: p.Source,
		CreatedAt:   now,
		UpdatedAt:   now,
		StateTimes:  map[ClipState]time.Time{StateDetected: now},
	}, nil
}

// Transition moves the clip to state to, validating the table. Use Fail to
// enter the failed state.
func (c *Clip) Transition(to ClipState, at time.Time) error {
	if to == StateFailed {
		return fmt.Errorf("%w: use Fail to enter %s", ErrInvalidTransition, StateFailed)
	}
	if !CanTransition(c.State, to) {
		return fmt.Errorf("%w: %s → %s (clip %s)", ErrInvalidTransition, c.State, to, c.ID)
	}
	at = at.UTC()
	if c.State == StatePreviewSent {
		switch to {
		case StateApproved:
			c.Decision, c.DecidedAt = DecisionApproved, at
		case StateDiscarded:
			c.Decision, c.DecidedAt = DecisionDiscarded, at
		case StateExpired:
			c.Decision, c.DecidedAt = DecisionExpired, at
		}
	}
	if c.State == StateFailed {
		// Manual retry: the failure is resolved.
		c.FailureReason, c.FailedFrom = "", ""
	}
	c.set(to, at)
	return nil
}

// Fail moves the clip to the failed state, recording the stage and reason.
func (c *Clip) Fail(reason string, at time.Time) error {
	if !CanTransition(c.State, StateFailed) {
		return fmt.Errorf("%w: %s → %s (clip %s)", ErrInvalidTransition, c.State, StateFailed, c.ID)
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		reason = "unknown error"
	}
	c.FailedFrom = c.State
	c.FailureReason = reason
	c.set(StateFailed, at.UTC())
	return nil
}

// MarkPublished records where the video was published and moves
// publishing → published.
func (c *Clip) MarkPublished(p Publication, at time.Time) error {
	if strings.TrimSpace(p.ID) == "" {
		return fmt.Errorf("%w: publication of clip %s has no id", ErrInvalidArgument, c.ID)
	}
	if err := c.Transition(StatePublished, at); err != nil {
		return err
	}
	c.PublishedID, c.PublishedURL, c.PublishError = p.ID, p.URL, ""
	return nil
}

// PublishFailed moves publishing → delivered keeping the reason, so the
// publication can be requested again.
func (c *Clip) PublishFailed(reason string, at time.Time) error {
	if c.State != StatePublishing {
		return fmt.Errorf("%w: %s is not publishing (clip %s)", ErrInvalidTransition, c.State, c.ID)
	}
	if err := c.Transition(StateDelivered, at); err != nil {
		return err
	}
	c.PublishError = strings.TrimSpace(reason)
	if c.PublishError == "" {
		c.PublishError = "unknown error"
	}
	return nil
}

func (c *Clip) set(to ClipState, at time.Time) {
	c.State = to
	c.UpdatedAt = at
	if c.StateTimes == nil {
		c.StateTimes = make(map[ClipState]time.Time)
	}
	c.StateTimes[to] = at
}

// EnteredAt returns when the clip last entered state s.
func (c *Clip) EnteredAt(s ClipState) (time.Time, bool) {
	t, ok := c.StateTimes[s]
	return t, ok
}

// ApprovalDeadline is when a preview stops accepting decisions.
func (c *Clip) ApprovalDeadline(ttl time.Duration) (time.Time, bool) {
	sent, ok := c.EnteredAt(StatePreviewSent)
	if !ok {
		return time.Time{}, false
	}
	return sent.Add(ttl), true
}

// IsExpired reports whether the clip awaits a decision past its deadline.
func (c *Clip) IsExpired(now time.Time, ttl time.Duration) bool {
	if c.State != StatePreviewSent {
		return false
	}
	deadline, ok := c.ApprovalDeadline(ttl)
	return ok && !now.Before(deadline)
}

// Clone returns a deep copy of the clip.
func (c *Clip) Clone() *Clip {
	if c == nil {
		return nil
	}
	cp := *c
	cp.Moment = c.Moment.Clone()
	cp.Timeline = slices.Clone(c.Timeline)
	if c.Plan != nil {
		plan := *c.Plan
		plan.Captions = slices.Clone(c.Plan.Captions)
		cp.Plan = &plan
	}
	if c.StateTimes != nil {
		cp.StateTimes = make(map[ClipState]time.Time, len(c.StateTimes))
		for k, v := range c.StateTimes {
			cp.StateTimes[k] = v
		}
	}
	return &cp
}
